INSERT INTO listings (id, vehicle_id, seller_id, title, description, price_eur, status, created_at, updated_at) VALUES
  (1, 1, 14, 'Audi Q5 35 TFSI', 'Well maintained Audi Q5 with a complete service history from an authorised workshop. Navigation, heated seats and a rear view camera are fitted. Timing belt and water pump were replaced during the last major service. Sold with a fresh inspection and a fully documented history.', 13890, 'ACTIVE', now() - interval '2761 hours', now() - interval '2761 hours'),
  (2, 2, 5, 'Mercedes-Benz A-Class A 180 d Exclusive', 'One owner Mercedes-Benz A-Class in very presentable condition inside and out. Winter and summer wheels are included in the price. Private sale, therefore without warranty or right of return.', 18490, 'ACTIVE', now() - interval '2540 hours', now() - interval '2540 hours'),
  (3, 3, 2, 'VW ID.3 Pro Performance United', 'Reliable VW ID.3 that has been serviced strictly according to the manufacturer schedule. Winter and summer wheels are included in the price. The most recent battery report is available for inspection on request. Financing can be arranged directly through our partner bank.', 25790, 'ACTIVE', now() - interval '642 hours', now() - interval '642 hours'),
  (4, 4, 13, 'Renault Clio dCi 85', 'Tidy Renault Clio sold directly by its owner in Kiel, ready to drive away. Air conditioning, cruise control and parking sensors are on board. Trade in of your current vehicle is possible after an on site valuation.', 8390, 'ACTIVE', now() - interval '2999 hours', now() - interval '2999 hours'),
  (5, 5, 12, 'BMW 3 Series 330i M Sport', 'Second owner BMW 3 Series that has spent most of its life on longer motorway runs. Air conditioning, cruise control and parking sensors are on board. Financing can be arranged directly through our partner bank.', 7690, 'ACTIVE', now() - interval '2171 hours', now() - interval '2171 hours'),
  (6, 6, 9, 'Tesla Model 3 Long Range AWD', 'One owner Tesla Model 3 in very presentable condition inside and out. Air conditioning, cruise control and parking sensors are on board. A type 2 charging cable is included and the charging port shows no wear. Delivery within northern Germany can be arranged on request.', 46290, 'ACTIVE', now() - interval '655 hours', now() - interval '655 hours'),
  (7, 7, 6, 'VW Golf 2.0 TSI Life', 'Carefully driven VW Golf in red, kept garaged and always serviced on time. Air conditioning, cruise control and parking sensors are on board. Financing can be arranged directly through our partner bank.', 7590, 'ACTIVE', now() - interval '2535 hours', now() - interval '2535 hours'),
  (8, 8, 7, 'Renault Clio SCe 65 Zen', 'Clean Renault Clio with a full stamp book and no accident history. Air conditioning, cruise control and parking sensors are on board. Timing belt and water pump were replaced during the last major service. Delivery within northern Germany can be arranged on request.', 5490, 'ACTIVE', now() - interval '2189 hours', now() - interval '2189 hours'),
  (9, 9, 12, 'Ford Fiesta 1.25 ST-Line', 'This Ford Fiesta comes from long term ownership and has been looked after properly. Winter and summer wheels are included in the price. The exhaust system and clutch were checked and are in good order. Delivery within northern Germany can be arranged on request.', 10590, 'ACTIVE', now() - interval '371 hours', now() - interval '371 hours'),
  (10, 10, 4, 'Tesla Model 3 Performance', 'One owner Tesla Model 3 in very presentable condition inside and out. Two keys, the full manual set and all service invoices are handed over. The most recent battery report is available for inspection on request. Financing can be arranged directly through our partner bank.', 34490, 'ACTIVE', now() - interval '1504 hours', now() - interval '1504 hours'),
  (11, 11, 4, 'Škoda Octavia 2.0 TSI Style', 'Tidy Škoda Octavia sold directly by its owner in Hamburg, ready to drive away. Two keys, the full manual set and all service invoices are handed over. The engine oil and filter were changed just before the sale. Trade in of your current vehicle is possible after an on site valuation.', 8890, 'ACTIVE', now() - interval '17 hours', now() - interval '17 hours'),
  (12, 12, 12, 'Renault Clio TCe 90 Techno', 'Reliable Renault Clio that has been serviced strictly according to the manufacturer schedule. Navigation, heated seats and a rear view camera are fitted. Timing belt and water pump were replaced during the last major service. Private sale, therefore without warranty or right of return.', 14990, 'ACTIVE', now() - interval '179 hours', now() - interval '179 hours'),
  (13, 13, 4, 'Mercedes-Benz GLC GLC 200 d Exclusive', 'Reliable Mercedes-Benz GLC that has been serviced strictly according to the manufacturer schedule. Navigation, heated seats and a rear view camera are fitted. Delivery within northern Germany can be arranged on request.', 50190, 'ACTIVE', now() - interval '2857 hours', now() - interval '2857 hours'),
  (14, 14, 15, 'VW Polo 1.4 TSI R-Line', 'Tidy VW Polo sold directly by its owner in Bremen, ready to drive away. Bodywork is straight with only minor stone chips on the front bumper. The exhaust system and clutch were checked and are in good order.', 12190, 'ACTIVE', now() - interval '1708 hours', now() - interval '1708 hours'),
  (15, 15, 10, 'Toyota Corolla 1.8 Hybrid Comfort', 'Reliable Toyota Corolla that has been serviced strictly according to the manufacturer schedule. The interior is free of smoke and shows only light wear on the driver seat. Sold with a fresh inspection and a fully documented history.', 10490, 'ACTIVE', now() - interval '981 hours', now() - interval '981 hours'),
  (16, 16, 5, 'Tesla Model 3 Performance', 'Second owner Tesla Model 3 that has spent most of its life on longer motorway runs. Winter and summer wheels are included in the price. A type 2 charging cable is included and the charging port shows no wear. Private sale, therefore without warranty or right of return.', 27390, 'ACTIVE', now() - interval '1721 hours', now() - interval '1721 hours'),
  (17, 17, 9, 'Ford Fiesta 1.1', 'Clean Ford Fiesta with a full stamp book and no accident history. Bodywork is straight with only minor stone chips on the front bumper.', 3690, 'ACTIVE', now() - interval '277 hours', now() - interval '277 hours'),
  (18, 18, 4, 'Audi A3 40 TFSI Sport', 'Tidy Audi A3 sold directly by its owner in Hamburg, ready to drive away. Navigation, heated seats and a rear view camera are fitted. The engine oil and filter were changed just before the sale. Sold with a fresh inspection and a fully documented history.', 37190, 'ACTIVE', now() - interval '2032 hours', now() - interval '2032 hours'),
